const websiteImportTierRefs = `-- name: WebsiteImportTierRefs :many
SELECT ref::text AS ref, count(*)::bigint AS posts
FROM website_import_posts, unnest(tier_refs) AS ref
WHERE import_id = $1 AND decision <> 'skip'
GROUP BY ref ORDER BY count(*) DESC, ref
`

type WebsiteImportTierRefsRow struct {
	Ref   string `json:"ref"`
	Posts int64  `json:"posts"`
}

// The old site's tiers the staged posts to import name, with how many posts each.
func (q *Queries) WebsiteImportTierRefs(ctx context.Context, importID uuid.UUID) ([]WebsiteImportTierRefsRow, error) {
	rows, err := q.db.Query(ctx, websiteImportTierRefs, importID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WebsiteImportTierRefsRow{}
	for rows.Next() {
		var i WebsiteImportTierRefsRow
		if err := rows.Scan(&i.Ref, &i.Posts); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const websiteImportTray = `-- name: WebsiteImportTray :many
SELECT id, source, status, stats, error, file_name, created_at, updated_at, finished_at
FROM website_imports
WHERE workspace_id = $1
  AND (status IN ('uploaded','analysing','importing') OR (status = 'ready' AND updated_at > $2::timestamptz)
       OR (status IN ('done','failed','canceled') AND finished_at > $2::timestamptz))
ORDER BY created_at DESC
LIMIT 20
`

type WebsiteImportTrayParams struct {
	WorkspaceID uuid.UUID `json:"workspaceId"`
	EndedAfter  time.Time `json:"endedAfter"`
}

type WebsiteImportTrayRow struct {
	ID         uuid.UUID       `json:"id"`
	Source     string          `json:"source"`
	Status     string          `json:"status"`
	Stats      json.RawMessage `json:"stats"`
	Error      string          `json:"error"`
	FileName   string          `json:"fileName"`
	CreatedAt  time.Time       `json:"createdAt"`
	UpdatedAt  time.Time       `json:"updatedAt"`
	FinishedAt *time.Time      `json:"finishedAt"`
}

// The imports the jobs tray shows: running ones, and ones that ended since.
func (q *Queries) WebsiteImportTray(ctx context.Context, arg WebsiteImportTrayParams) ([]WebsiteImportTrayRow, error) {
	rows, err := q.db.Query(ctx, websiteImportTray, arg.WorkspaceID, arg.EndedAfter)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WebsiteImportTrayRow{}
	for rows.Next() {
		var i WebsiteImportTrayRow
		if err := rows.Scan(
			&i.ID,
			&i.Source,
			&i.Status,
			&i.Stats,
			&i.Error,
			&i.FileName,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.FinishedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

